import json, sqlite3
with open('json/schools.json') as f: schools = {s['CDSCode']:s for s in json.load(f)['records']}
con = sqlite3.connect('db/satscores.db')
cur = con.execute('SELECT cds, AvgScrRead FROM satscores WHERE dname="Fresno Unified" AND AvgScrRead IS NOT NULL')
results = cur.fetchall()
con.close()
min_score = float('inf')
min_school = None
for cds, score in results:
    if score < min_score:
        min_score = score
        min_school = schools.get(cds, {})
if min_school:
    print(f"School: {min_school.get('School Name')}, Phone: {min_school.get('Phone')}, AvgRead: {min_score}")
else:
